const items = $input.all();
const first = items[0]?.json ?? {};
let config = first;
try {
  const setVariables = $('Set Variables').first().json;
  if (setVariables?.file_changed) config = setVariables;
} catch {}

const values = items.map((item) => {
  const json = item.json ?? {};
  if (typeof json.data === 'string') return json.data;
  if (typeof json.text === 'string') return json.text;
  return Object.entries(json)
    .map(([key, value]) => key + ': ' + (typeof value === 'object' ? JSON.stringify(value) : String(value)))
    .join('\t');
}).filter((value) => value.trim().length > 0);

const extractedText = values.join('\n').trim();
if (!extractedText) {
  throw new Error('No searchable text was extracted. Scanned PDFs and images require OCR.');
}

const fileName = config.fileName || first.fileName || 'knowledge-upload';
const fileLocation = config.file_changed || first.file_changed || '/knowledge-files/' + fileName;
const fileExtension = config.fileExtension || fileName.split('.').pop().toLowerCase();
const data = [
  '## file location',
  fileLocation,
  '## file created',
  new Date().toISOString(),
  '## file contents',
  extractedText,
].join('\n');

return [{
  json: {
    directory: config.directory || '/knowledge-files',
    fileName,
    file_changed: fileLocation,
    file_added: '',
    file_location: fileLocation,
    fileExtension,
    qdrant_collection: config.qdrant_collection || 'hragent_knowledge',
    data,
  },
}];

const encodedPdf = (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('base64');
return [{
  json: {
    fileName: $('Set Variables').first().json.fileName,
    data: encodedPdf,
  },
}];

const meta = $('Normalize Extracted Content').first().json;
return [{ json: {
  success: true,
  fileName: meta.fileName,
  collection: meta.qdrant_collection,
  message: 'Knowledge vectors indexed',
} }];
